# c3base checklist, read-only ON cv02 (G: ssh -a -o BatchMode=yes cv02@10.8.1.106 "bash -s" < c3_rv_cv02.sh). Writes nothing.
B=/tmp/noob_el/bench_89b9ea5; D=/tmp/noob_el/bench_data_v3b; Q=/tmp/noob_el/bench_q/c3base; X=/tmp/noob_el/bench_data
P=/tmp/noob_el/el-fault-detection/.venv/bin/python
date -u '+%F %T UTC'
echo "1 code: REVISION $(cat $B/REVISION); CODE.md5 $(md5sum < $B/CODE.md5 | cut -c1-8) $(cd $B && md5sum -c --quiet CODE.md5 > /dev/null 2>&1 && echo OK || echo FAIL); cq.sh $(md5sum < $B/bench/q/cv02/cq.sh | cut -c1-8); experiments $(ls $B/experiments 2>/dev/null | wc -l) runs $(ls $B/runs 2>/dev/null | wc -l) dumps $(find $B/dumps -type f 2>/dev/null | wc -l)"
echo "2 masks: $(cd $X/masks_v11 && md5sum -c --quiet MANIFEST.md5 > /dev/null 2>&1 && echo MASKS_OK || echo MASKS_FAIL) $(md5sum < $X/masks_v11/MANIFEST.md5 | cut -c1-8); DEPLOY.md5 $(md5sum < $X/DEPLOY.md5 | cut -c1-8)"
echo "3 meta: $(cd $D/meta && md5sum -c --quiet META.md5 > /dev/null 2>&1 && echo OK || echo FAIL) $(md5sum < $D/meta/META.md5 | cut -c1-8); roots: $(cd $D/roots && md5sum -c --quiet ROOTS_cv5v3_v11.md5 > /dev/null 2>&1 && echo OK || echo FAIL) $(md5sum < $D/roots/ROOTS_cv5v3_v11.md5 | cut -c1-8)"
(cd $B && CUDA_VISIBLE_DEVICES= nice -n 19 $P scripts/bench_make_roots.py --split $D/meta/cv5v3.json --groups $D/meta/cv5v3_groups.tsv --forbidden $D/meta/forbidden_v1.txt --legacy-splits data/splits --labeled $X/labeled --out $D/roots --tag v11 --train-masks $X/masks_v11/masks --heldout-masks $X/masks_v11/masks_strict --link-dir masks_v11 --check 2>&1 | tail -2)
for k in 0 1 2 3 4; do r=$D/roots/cv5v3_v11_f$k; echo "4 f$k: train $(grep -c . $r/splits/train.txt) held $(grep -c . $r/splits/test.txt) test=val $(cmp -s $r/splits/val.txt $r/splits/test.txt && echo y || echo n); train->masks $(awk -F'\t' -v m=$X/masks_v11/masks/ '$2=="train" && index($3,m)==1' $r/MASKLINKS.tsv | wc -l), held->strict $(awk -F'\t' -v m=$X/masks_v11/masks_strict/ '$2=="heldout" && index($3,m)==1' $r/MASKLINKS.tsv | wc -l), dangling $(find $r/masks_v11 -xtype l | wc -l)"; done
echo "5 cards: $(cd $B && for c in house_r34_unetpp_pf_v11 house_r34_unetpp_v11; do echo -n "$c $(md5sum < bench/methods/$c.yaml | cut -c1-8) cv02 $(md5sum < bench/methods_cv02/$c.yaml | cut -c1-8) [$($P bench/q/cv02/cvcard.py bench/methods/$c.yaml bench/methods_cv02/$c.yaml | while read m f; do [ "$(md5sum < $f | cut -c1-32)" = "$m" ] && echo -n "weights OK " || echo -n "weights FAIL "; done)] "; done)"
echo "6 queue: $(ls $Q | tr '\n' ' '); jobs $(md5sum < $Q/jobs.txt | cut -c1-32) $(grep -c . $Q/jobs.txt) lines; LPG $(cat $Q/LPG) MAXC $(cat $Q/MAXC); existing experiments/<name>: $(cut -d'|' -f1 $Q/jobs.txt | while read n; do [ -e $B/experiments/$n ] || [ -e $B/experiments/$n.stdout ] && echo $n; done | wc -l)"
echo "7 sessions bench_q_c3base*: $(tmux ls 2>/dev/null | grep -c '^bench_q_c3base'); rows2 alive: $(tmux has-session -t '=bench_q_rows2' 2>/dev/null && echo yes || echo no); pattern kills in bench/q: $(grep -rnE 'pkill|killall|pgrep|xargs.*kill' $B/bench/q | wc -l); smoke dirs: $(ls -d /tmp/noob_el/bench_q/c3base_smoke* | tr '\n' ' ')"
df -h /tmp | tail -1
